"""Read-only counters used identically for the before/after observations."""
import functools
import json
import os
from pathlib import Path
import subprocess
import sys
import time
from collections import Counter, defaultdict

import pytest

COUNTS = defaultdict(Counter)
SECONDS = defaultdict(Counter)
ROOTS = set()
DATA = []
FITS = []
MODELS = []
NODE = 'session'


def wrap(owner, name, label):
    original = getattr(owner, name)
    @functools.wraps(original)
    def observed(*args, **kwargs):
        COUNTS[NODE][label] += 1
        start = time.perf_counter()
        try:
            return original(*args, **kwargs)
        finally:
            SECONDS[NODE][label] += time.perf_counter() - start
    setattr(owner, name, observed)


def pytest_collection_finish(session):
    if not hasattr(session.config, 'workerinput'):
        return
    parent = sys.modules.get('tests.e2e.agents_ops.test_parent_session')
    if parent:
        wrap(parent.ParentEnv, 'cli', 'parent_cli')
        wrap(parent.ReviewEnv, 'cli', 'review_cli')
    gate = sys.modules.get('tests.e2e.agents_ops.test_merge_gate')
    if gate:
        wrap(gate.GateEnv, 'cli', 'gate_cli')
        if hasattr(gate, 'GateSeed'):
            original_restore = gate.GateSeed.restore
            @functools.wraps(original_restore)
            def restore(self, p, *args, **kwargs):
                COUNTS[NODE]['seed_restore'] += 1
                COUNTS[NODE]['restored_fake_github_calls'] += len((self.directory.snapshot / 'calls.jsonl').read_text().splitlines())
                ROOTS.add(p.root)
                return original_restore(self, p, *args, **kwargs)
            gate.GateSeed.restore = restore
    runner = sys.modules.get('src.tasks.ball_refiner_3d.training.runner')
    if runner:
        wrap(runner.RefinerTrainingRunner, 'run', 'training_run')
        original_build = runner.RefinerTrainingRunner.build_lightning_module
        @functools.wraps(original_build)
        def build(self, *args, **kwargs):
            model = original_build(self, *args, **kwargs)
            COUNTS[NODE]['model_init'] += 1
            MODELS.append({'nodeid': NODE, 'parameters': sum(p.numel() for p in model.parameters())})
            return model
        runner.RefinerTrainingRunner.build_lightning_module = build
    physics = sys.modules.get('src.tasks.ball_refiner_3d.evaluation.physics')
    if physics:
        original_fit = physics.fit_flight_physics
        @functools.wraps(original_fit)
        def fit(trajectories, segments, settings, *args, **kwargs):
            COUNTS[NODE]['physics_fit'] += 1
            start = time.perf_counter()
            try:
                return original_fit(trajectories, segments, settings, *args, **kwargs)
            finally:
                elapsed = time.perf_counter() - start
                SECONDS[NODE]['physics_fit'] += elapsed
                FITS.append({'nodeid': NODE, 'seconds': elapsed, 'frames': [len(t) for t in trajectories], 'starts': len(settings.field_starts), 'segment_iterations': settings.segment_iterations, 'iterations': settings.iterations})
        physics.fit_flight_physics = fit
    evaluator = sys.modules.get('src.tasks.ball_refiner_3d.evaluation.evaluator')
    if evaluator:
        original = evaluator.evaluate
        for module in list(sys.modules.values()):
            if module and getattr(module, '__name__', '').startswith(('src.tasks.ball_refiner_3d', 'tests.integration.tasks.ball_refiner_3d')):
                if getattr(module, 'evaluate', None) is original:
                    wrap(module, 'evaluate', 'evaluate')
    import torch
    wrap(torch, 'save', 'torch_save')
    wrap(torch.optim.AdamW, 'step', 'optimizer_step')
    original_run = subprocess.run
    @functools.wraps(original_run)
    def run(command, *args, **kwargs):
        if isinstance(command, (tuple, list)) and command and command[0] == 'git':
            COUNTS[NODE]['git'] += 1
            if len(command) > 1:
                COUNTS[NODE]['git_' + command[1]] += 1
                if command[1:3] == ['worktree', 'add']:
                    COUNTS[NODE]['worktree_add'] += 1
        return original_run(command, *args, **kwargs)
    subprocess.run = run


@pytest.hookimpl(wrapper=True)
def pytest_runtest_protocol(item, nextitem):
    global NODE
    NODE = item.nodeid
    try:
        return (yield)
    finally:
        NODE = 'session'


@pytest.hookimpl(wrapper=True)
def pytest_fixture_setup(fixturedef, request):
    result = yield
    if fixturedef.argname in ('parent_env', 'gate_env', 'shared'):
        COUNTS[NODE]['fixture_' + fixturedef.argname] += 1
    if fixturedef.argname == 'parent_env':
        ROOTS.add(result.root)
    if fixturedef.argname == 'shared' and 'test_coordinates_training' in request.node.nodeid:
        manifest = json.loads((result[1] / 'manifest.json').read_text())
        DATA.append({'records': [{'frames': r['frames'], 'split': r['split']} for r in manifest['records']], 'generation_seconds': manifest['generation_seconds']})
    return result


def pytest_sessionfinish(session, exitstatus):
    if not hasattr(session.config, 'workerinput'):
        return
    calls = []
    for root in ROOTS:
        path = root / 'calls.jsonl'
        if path.exists():
            calls.extend(json.loads(line) for line in path.read_text().splitlines())
    root = Path(os.environ['HEAVY_OBSERVER_DIR'])
    root.mkdir(parents=True, exist_ok=True)
    restored = sum(c.get('restored_fake_github_calls', 0) for c in COUNTS.values())
    (root / (os.environ['PYTEST_XDIST_WORKER'] + '.json')).write_text(json.dumps({'counts': dict(COUNTS), 'seconds': dict(SECONDS), 'fake_github_calls': len(calls) - restored, 'fake_github_calls_including_copies': len(calls), 'restored_fake_github_calls': restored, 'fake_github_operations_including_copies': dict(Counter(' '.join(c[:2]) for c in calls)), 'datasets': DATA, 'fits': FITS, 'models': MODELS, 'exitstatus': int(exitstatus)}, indent=2))
